DEFAULT_PROFILE_ROOT = "~/.thunderbird"
DEFAULT_PROFILES_INI = "~/.thunderbird/profiles.ini"


def read_calendar_evidence(
    controller: Any,
    params: Mapping[str, Any],
    *,
    profile_root: str | None = None,
    profiles_ini: str | None = None,
) -> dict[str, Any]:
    """Return the Thunderbird calendar evidence mapping for the declared profile."""
    root = str(profile_root or params.get("profile_root") or DEFAULT_PROFILE_ROOT)
    ini = str(profiles_ini or params.get("profiles_ini") or DEFAULT_PROFILES_INI)
    declared = params.get("profile_dirs") or params.get("profile_dir") or []
    if isinstance(declared, str):
        declared = [declared]
    script = (
        GUEST_EVIDENCE_SCRIPT.replace("__PROFILE_ROOT__", repr(root))
        .replace("__PROFILES_INI__", repr(ini))
        .replace("__PROFILE_DIRS__", repr([str(item) for item in declared]))
        .strip()
    )
    if controller is None or not hasattr(controller, "run_python_script"):
        raise RuntimeError("controller.run_python_script is required")
    result = controller.run_python_script(script, timeout=int(params.get("timeout") or 60))
    output = str(result.get("stdout") or result.get("output") or "").strip()
    if int(result.get("returncode", -1)) != 0:
        raise RuntimeError(str(result.get("stderr") or "") or output or "guest evidence script failed")
    payload = json.loads(output.splitlines()[-1])
    state = payload.get("thunderbird_calendar")
    if not isinstance(state, Mapping):
        raise TypeError("guest payload has no thunderbird_calendar state")
    return dict(state)


class ThunderbirdCalendarEvaluator(BaseEvaluator):
    """Verify Thunderbird calendar events recorded in the profile database."""

    DEFAULT_PROFILE_ROOT = DEFAULT_PROFILE_ROOT
    DEFAULT_PROFILES_INI = DEFAULT_PROFILES_INI
    PASS_MESSAGE = "Thunderbird calendar checks passed"
    FAIL_MESSAGE = "Thunderbird calendar checks failed"
    DATA_SOURCES = [
        "read-only Thunderbird calendar-data/local.sqlite snapshot including WAL",
        "Thunderbird prefs.js calendar.registry names",
        "Thunderbird profiles.ini profile discovery",
    ]

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = self._context_params(context)
        metadata = self._empty_metadata(params)

        if not self._has_requirements(params):
            metadata["status"] = "fail"
            metadata["message"] = "the task declares no calendar records to verify"
            return EvalResult(status=EvalStatus.FAIL, message=metadata["message"], metadata=metadata)

        try:
            evidence = read_calendar_evidence(context.get("controller"), params)
        except Exception as exc:
            reason = "Thunderbird calendar evidence could not be read: %s: %s" % (type(exc).__name__, exc)
            metadata["status"] = "fail"
            metadata["message"] = reason
            self._record(metadata, "evidence_read", False, {"readable_calendar": True}, {"error": reason}, reason)
            return EvalResult(status=EvalStatus.FAIL, message=reason, metadata=metadata)

        selected, profiles = self._select_profile(evidence)
        if selected is None:
            reason = "no Thunderbird calendar profile database was found under %s" % (
                evidence.get("profile_root") or params.get("profile_root") or DEFAULT_PROFILE_ROOT
            )
            metadata["status"] = "fail"
            metadata["message"] = reason
            self._record(metadata, "evidence_read", False, {"calendar_database": "present"}, {"discovery": evidence.get("profile_discovery")}, reason)
            return EvalResult(status=EvalStatus.FAIL, message=reason, metadata=metadata)

        if selected.get("calendar_error"):
            reason = "the Thunderbird calendar database could not be read: %s" % selected["calendar_error"]
            metadata["status"] = "fail"
            metadata["message"] = reason
            self._record(metadata, "evidence_read", False, {"calendar_database": "readable"}, {"error": selected["calendar_error"]}, reason)
            return EvalResult(status=EvalStatus.FAIL, message=reason, metadata=metadata)

        if not selected.get("calendar_db_exists") and not selected.get("events"):
            reason = "the Thunderbird calendar database is absent for profile %s" % (
                selected.get("path") or selected.get("profile")
            )
            metadata["status"] = "fail"
            metadata["message"] = reason
            self._record(metadata, "evidence_read", False, {"calendar_database": "present"}, {"profile": selected.get("profile")}, reason)
            return EvalResult(status=EvalStatus.FAIL, message=reason, metadata=metadata)

        discovery = evidence.get("profile_discovery") or {}
        selected_meta = discovery.get("selected") if isinstance(discovery, Mapping) else None
        metadata["profile_dir"] = str((selected_meta or {}).get("path") or selected.get("path") or "")
        metadata["db_path"] = str((selected_meta or {}).get("db_path") or selected.get("calendar_db") or "")
        metadata["profile_discovery"] = discovery
        metadata["read_source"] = evidence.get("read_source") or {}
        metadata["reference_time_local"] = evidence.get("reference_time_local")
        metadata["reference_timezone"] = evidence.get("reference_timezone")

        events = [event for event in (selected.get("events") or []) if isinstance(event, Mapping)]
        masters = [event for event in events if not event.get("recurrence_id")]
        overrides = [event for event in events if event.get("recurrence_id")]
        metadata["observed"] = {
            "profile_count": len(profiles),
            "event_row_count": len(events),
            "master_event_count": len(masters),
            "occurrence_override_count": len(overrides),
            "calendar_names": dict(selected.get("calendar_names") or {}),
            "read_source_mode": (evidence.get("read_source") or {}).get("mode"),
        }
        metadata["occurrence_exceptions"] = self._group_overrides(selected, overrides)

        reference = self._reference_datetime(params, evidence)
        self._check_titles(metadata, selected, masters, params)
        self._check_title_counts(metadata, masters, params)
        self._check_event_expectations(metadata, selected, masters, params, reference)
        self._check_recurrences(metadata, selected, masters, params)
        self._check_final_view(context, params, metadata)

        if not metadata["checks"]:
            metadata["status"] = "fail"
            metadata["message"] = "the declared calendar requirements produced no comparable record"
            return EvalResult(status=EvalStatus.FAIL, message=metadata["message"], metadata=metadata)

        failed = [check["check_id"] for check in metadata["checks"] if not check["passed"]]
        if failed:
            metadata["status"] = "fail"
            message = "Thunderbird calendar checks failed (%d/%d): %s" % (
                len(failed),
                len(metadata["checks"]),
                ", ".join(failed[:8]),
            )
            metadata["message"] = message
            return EvalResult(status=EvalStatus.FAIL, message=message, metadata=metadata)

        metadata["status"] = "pass"
        metadata["message"] = self.PASS_MESSAGE
        return EvalResult(status=EvalStatus.PASS, message=self.PASS_MESSAGE, metadata=metadata)

    # --------------------------------------------------------------- checks
    def _check_titles(
        self,
        metadata: dict[str, Any],
        profile: Mapping[str, Any],
        masters: list[Mapping[str, Any]],
        params: Mapping[str, Any],
    ) -> None:
        titles = [str(title) for title in (params.get("required_titles") or [])]
        if not titles:
            for source in (params.get("expected_title_counts") or {}, params.get("event_expectations") or {}):
                for title in source:
                    if title not in titles:
                        titles.append(title)
        for title in titles:
            hits = [self._event_summary(profile, event) for event in masters if self._title_of(event) == title]
            metadata["required_hits"][title] = hits
            passed = bool(hits)
            if not passed:
                metadata["missing_required"].append(title)
            self._record(
                metadata,
                "title:%s" % title,
                passed,
                {"title": title},
                hits,
                "required Thunderbird calendar event title is missing: %s" % title,
            )

        for title in params.get("forbidden_titles") or []:
            title = str(title)
            hits = [self._event_summary(profile, event) for event in masters if self._title_of(event) == title]
            metadata["forbidden_hits"][title] = hits
            if hits:
                metadata["forbidden_present"].append(title)
            self._record(
                metadata,
                "forbidden_title:%s" % title,
                not hits,
                {"title": title, "count": 0},
                hits,
                "forbidden Thunderbird calendar event title is present: %s" % title,
            )

    def _check_title_counts(
        self,
        metadata: dict[str, Any],
        masters: list[Mapping[str, Any]],
        params: Mapping[str, Any],
    ) -> None:
        for title, raw_count in (params.get("expected_title_counts") or {}).items():
            title = str(title)
            try:
                expected_count = int(raw_count)
            except (TypeError, ValueError):
                metadata["title_count_mismatches"].append({"title": title, "expected": raw_count, "observed": None})
                self._record(metadata, "title_count:%s" % title, False, {"count": raw_count}, {"count": None},
                             "expected_title_counts[%s] is not an integer" % title)
                continue
            observed_count = sum(1 for event in masters if self._title_of(event) == title)
            passed = observed_count == expected_count
            if not passed:
                metadata["title_count_mismatches"].append(
                    {"title": title, "expected": expected_count, "observed": observed_count}
                )
            self._record(
                metadata,
                "title_count:%s" % title,
                passed,
                {"count": expected_count},
                {"count": observed_count},
                "expected exactly %d '%s' event(s), observed %d" % (expected_count, title, observed_count),
            )

    def _check_recurrences(
        self,
        metadata: dict[str, Any],
        profile: Mapping[str, Any],
        masters: list[Mapping[str, Any]],
        params: Mapping[str, Any],
    ) -> None:
        for title, raw_keywords in (params.get("recurrence_checks") or {}).items():
            title = str(title)
            keywords = [str(keyword) for keyword in (raw_keywords or [])]
            hits = []
            for event in masters:
                if self._title_of(event) != title:
                    continue
                recurrence = self._recurrence_strings(profile, event)
                joined = "\n".join(recurrence).casefold()
                matched = [keyword for keyword in keywords if keyword.casefold() in joined]
                if keywords and len(matched) == len(keywords):
                    hits.append(
                        {
                            "event": self._event_summary(profile, event),
                            "matched_keywords": matched,
                            "recurrence": recurrence,
                            "alarms": self._alarm_strings(profile, event),
                        }
                    )
            metadata["recurrence_hits"][title] = hits
            passed = bool(hits)
            if not passed:
                metadata["missing_recurrence"].append(title)
            self._record(
                metadata,
                "recurrence:%s" % title,
                passed,
                {"keywords": keywords},
                hits,
                "Thunderbird calendar event '%s' does not carry the required recurrence %s" % (title, keywords),
            )

    def _check_event_expectations(
        self,
        metadata: dict[str, Any],
        profile: Mapping[str, Any],
        masters: list[Mapping[str, Any]],
        params: Mapping[str, Any],
        reference: datetime | None,
    ) -> None:
        for title, raw_expected in (params.get("event_expectations") or {}).items():
            title = str(title)
            if not isinstance(raw_expected, Mapping):
                metadata["event_expectation_errors"].append({"title": title, "error": "expectation is not a mapping"})
                continue
            expected = dict(raw_expected)
            candidates = []
            hits = []
            for event in masters:
                if self._title_of(event) != title:
                    continue
                detail = self._event_detail(profile, event, expected, params, title, reference)
                candidates.append(detail)
                if all(value is not False for value in detail["checks"].values()):
                    hits.append(detail)
            metadata["event_expectation_candidates"][title] = candidates
            metadata["event_expectation_hits"][title] = hits
            passed = bool(hits)
            if not passed:
                metadata["missing_event_expectations"].append(title)
            self._record(
                metadata,
                "event:%s" % title,
                passed,
                expected,
                candidates,
                self._event_failure_reason(title, candidates),
            )

    def _check_final_view(
        self,
        context: Mapping[str, Any],
        params: Mapping[str, Any],
        metadata: dict[str, Any],
    ) -> None:
        view = str(params.get("final_view") or "").strip()
        if not view:
            return
        observed = self._final_view_observed(context.get("final_observation"), view)
        if not observed.get("foreground_app") and not observed.get("ui_node_count"):
            metadata["final_view_check"] = {"skipped": True, "reason": "no accessibility observation was available"}
            return
        app = str(observed["foreground_app"]).casefold()
        foreground_ok = "thunderbird" in app
        view_ok = bool(
            observed.get("matching_nodes")
            or observed.get("calendar_selected_nodes")
            or observed.get("selected_nodes")
            or observed.get(self._view_node_key(view))
        )
        passed = foreground_ok and view_ok
        reason = ""
        if not passed:
            reason = (
                "final accessibility observation does not show Thunderbird in the foreground"
                if not foreground_ok
                else "final accessibility observation does not show the Thunderbird Calendar %s view" % view
            )
        check = {
            "check_id": "final_view:%s" % view,
            "passed": bool(passed),
            "expected": {"foreground_app": "Thunderbird", "selected_calendar_view": view},
            "observed": observed,
            "failure_reason": reason,
        }
        metadata["final_view_check"] = check
        metadata["checks"].append(check)
        if reason:
            metadata["failure_reasons"].append(reason)

    # ------------------------------------------------------- event details
    def _event_detail(
        self,
        profile: Mapping[str, Any],
        event: Mapping[str, Any],
        expected: Mapping[str, Any],
        params: Mapping[str, Any],
        title: str,
        reference: datetime | None,
    ) -> dict[str, Any]:
        start = self._from_microseconds(event.get("event_start"), event.get("event_start_tz"))
        end = self._from_microseconds(event.get("event_end"), event.get("event_end_tz"))
        business = self._business_values(profile, event)
        recurrence = self._recurrence_strings(profile, event)
        alarms = self._alarm_strings(profile, event)

        checks: dict[str, Any] = {}
        skipped: list[str] = []

        expected_date = self._parse_date(expected.get("date"))
        if expected_date is None and expected.get("days_from_today") is not None and reference is not None:
            try:
                expected_date = (reference + timedelta(days=int(expected["days_from_today"]))).date()
            except (TypeError, ValueError):
                expected_date = None
        if expected_date is not None:
            checks["date"] = bool(start is not None and start.date() == expected_date)
            checks["weekday"] = bool(
                start is not None and start.strftime("%A").casefold() == expected_date.strftime("%A").casefold()
            )
        else:
            checks["date"] = None
            checks["weekday"] = None
            skipped.extend(["date", "weekday"])

        expected_weekday = expected.get("weekday")
        if expected_weekday:
            checks["weekday_name"] = bool(
                start is not None and start.strftime("%A").casefold() == str(expected_weekday).casefold()
            )
        else:
            checks["weekday_name"] = None

        expected_time = self._parse_hhmm(expected.get("start_time"))
        if expected.get("start_time") is not None:
            checks["time"] = bool(start is not None and start.strftime("%H:%M") == expected_time)
        else:
            checks["time"] = None
            skipped.append("time")

        if expected.get("duration_minutes") is not None:
            try:
                wanted = float(expected["duration_minutes"])
                checks["duration"] = bool(
                    start is not None and end is not None and abs((end - start).total_seconds() / 60.0 - wanted) < 1e-6
                )
            except (TypeError, ValueError):
                checks["duration"] = False
        else:
            checks["duration"] = None
            skipped.append("duration")

        recurrence_keywords = expected.get("recurrence_keywords")
        if recurrence_keywords is None:
            recurrence_keywords = (params.get("recurrence_checks") or {}).get(title)
        if recurrence_keywords:
            joined = "\n".join(recurrence).casefold()
            checks["recurrence"] = all(str(keyword).casefold() in joined for keyword in recurrence_keywords)
        else:
            checks["recurrence"] = None
            skipped.append("recurrence")

        alarm_keywords = expected.get("alarm_keywords")
        if alarm_keywords:
            joined = "\n".join(alarms).casefold()
            checks["alarm"] = all(str(keyword).casefold() in joined for keyword in alarm_keywords)
        else:
            checks["alarm"] = None
            skipped.append("alarm")

        for name, wanted, values in (
            ("location", expected.get("location"), business["locations"]),
            ("description", expected.get("description"), business["descriptions"]),
        ):
            if wanted is None:
                checks[name] = None
                skipped.append(name)
                continue
            checks[name] = any(self._normalize(value) == self._normalize(wanted) for value in values)

        category = expected.get("category")
        if category is not None:
            wanted = self._normalize(category)
            tokens = [self._normalize(part) for value in business["categories"] for part in str(value).split(",")]
            checks["category"] = wanted in tokens or wanted in [self._normalize(value) for value in business["categories"]]
        else:
            checks["category"] = None
            skipped.append("category")

        property_keywords = expected.get("property_keywords")
        if property_keywords:
            corpus = "\n".join(str(row.get("value") or "") for row in business["properties"])
            checks["property"] = all(str(keyword).casefold() in corpus.casefold() for keyword in property_keywords)
        else:
            checks["property"] = None
            skipped.append("property")

        calendar = expected.get("calendar")
        if calendar is not None:
            observed_name = business.get("calendar_name")
            checks["calendar"] = observed_name is not None and self._normalize(observed_name) == self._normalize(calendar)
        else:
            checks["calendar"] = None
            skipped.append("calendar")

        return {
            "event": self._event_summary(profile, event),
            "checks": checks,
            "skipped": skipped,
            "observed_start_local": start.isoformat() if start is not None else None,
            "observed_end_local": end.isoformat() if end is not None else None,
            "expected_date": expected_date.isoformat() if expected_date is not None else None,
            "recurrence": recurrence,
            "alarms": alarms,
            "business_values": business,
        }

    @staticmethod
    def _event_failure_reason(title: str, candidates: list[Mapping[str, Any]]) -> str:
        if not candidates:
            return "required Thunderbird calendar event is missing: %s" % title
        best = min(candidates, key=lambda item: sum(1 for value in item["checks"].values() if value is False))
        failures = [name for name, value in best["checks"].items() if value is False]
        return "Thunderbird calendar event '%s' failed %s (%d candidate event(s) inspected)" % (
            title,
            ", ".join(failures) or "no comparable field",
            len(candidates),
        )

    # ------------------------------------------------------------- helpers
    @staticmethod
    def _has_requirements(params: Mapping[str, Any]) -> bool:
        return any(
            params.get(key)
            for key in (
                "required_titles",
                "expected_title_counts",
                "event_expectations",
                "recurrence_checks",
                "final_view",
            )
        )

    def _empty_metadata(self, params: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "status": "fail",
            "message": "",
            "checks": [],
            "failure_reasons": [],
            "observed": {},
            "profile_dir": None,
            "db_path": None,
            "required_hits": {},
            "forbidden_hits": {},
            "forbidden_present": [],
            "recurrence_hits": {},
            "event_expectation_hits": {},
            "event_expectation_candidates": {},
            "missing_required": [],
            "title_count_mismatches": [],
            "missing_recurrence": [],
            "missing_event_expectations": [],
            "event_expectation_errors": [],
            "occurrence_exceptions": {},
            "profile_discovery": {},
            "read_source": {},
            "reference_time_local": None,
            "reference_timezone": None,
            "data_sources": list(self.DATA_SOURCES),
            "state_modified": False,
        }

    @staticmethod
    def _record(
        metadata: dict[str, Any],
        check_id: str,
        passed: bool,
        expected: Any,
        observed: Any,
        failure_reason: str,
    ) -> None:
        reason = "" if passed else failure_reason
        metadata["checks"].append(
            {
                "check_id": check_id,
                "passed": bool(passed),
                "expected": expected,
                "observed": observed,
                "failure_reason": reason,
            }
        )
        if reason:
            metadata["failure_reasons"].append(reason)

    @staticmethod
    def _select_profile(evidence: Mapping[str, Any]) -> tuple[dict[str, Any] | None, list[Mapping[str, Any]]]:
        profiles = [profile for profile in (evidence.get("profiles") or []) if isinstance(profile, Mapping)]
        discovery = evidence.get("profile_discovery")
        selected_meta = discovery.get("selected") if isinstance(discovery, Mapping) else None
        selected_path = str(selected_meta.get("path") or "") if isinstance(selected_meta, Mapping) else ""
        selected = None
        if selected_path:
            selected = next(
                (
                    profile
                    for profile in profiles
                    if str(profile.get("path") or "") == selected_path
                    and (profile.get("calendar_db_exists") or profile.get("events"))
                ),
                None,
            )
        if selected is None:
            selected = next(
                (profile for profile in profiles if profile.get("calendar_db_exists") or profile.get("events")),
                None,
            )
        if selected is None and profiles:
            selected = dict(profiles[0])
        if selected is not None:
            selected = dict(selected)
        return selected, profiles

    @staticmethod
    def _title_of(event: Mapping[str, Any]) -> str:
        return str(event.get("title") or "").strip()

    @staticmethod
    def _event_summary(profile: Mapping[str, Any], event: Mapping[str, Any]) -> dict[str, Any]:
        summary = dict(event)
        names = profile.get("calendar_names") or {}
        cal_id = str(event.get("cal_id") or "")
        if cal_id in names:
            summary["calendar_name"] = names[cal_id]
        return summary

    def _group_overrides(
        self, profile: Mapping[str, Any], overrides: list[Mapping[str, Any]]
    ) -> dict[str, list[dict[str, Any]]]:
        grouped: dict[str, list[dict[str, Any]]] = {}
        for event in overrides:
            grouped.setdefault(self._title_of(event), []).append(self._event_summary(profile, event))
        return grouped

    def _business_values(self, profile: Mapping[str, Any], event: Mapping[str, Any]) -> dict[str, Any]:
        locations: list[str] = []
        descriptions: list[str] = []
        categories: list[str] = []
        rows: list[dict[str, Any]] = []
        item_id = str(event.get("id") or "")
        cal_id = str(event.get("cal_id") or "")
        recurrence_id = event.get("recurrence_id") or None

        for prop in profile.get("properties") or []:
            if not isinstance(prop, Mapping):
                continue
            if str(prop.get("item_id") or "") != item_id or str(prop.get("cal_id") or "") != cal_id:
                continue
            if (prop.get("recurrence_id") or None) != recurrence_id:
                continue
            value = prop.get("value")
            if value is None:
                continue
            key = str(prop.get("key") or "")
            rows.append({"key": key, "value": value})
            text = str(value)
            if key == "LOCATION":
                locations.append(text)
            elif key == "DESCRIPTION":
                descriptions.append(text)
            elif key == "CATEGORIES":
                categories.append(text)

        if not rows:
            if event.get("location") is not None:
                locations.append(str(event["location"]))
            if event.get("description") is not None:
                descriptions.append(str(event["description"]))
            if event.get("categories") is not None:
                categories.append(str(event["categories"]))

        name = event.get("calendar_name") or (profile.get("calendar_names") or {}).get(cal_id)
        return {
            "locations": locations,
            "descriptions": descriptions,
            "categories": categories,
            "calendar_name": name,
            "properties": rows,
        }

    @staticmethod
    def _alarm_strings(profile: Mapping[str, Any], event: Mapping[str, Any]) -> list[str]:
        item_id = str(event.get("id") or "")
        cal_id = str(event.get("cal_id") or "")
        out = []
        for alarm in profile.get("alarms") or []:
            if not isinstance(alarm, Mapping):
                continue
            if str(alarm.get("item_id") or "") != item_id or str(alarm.get("cal_id") or "") != cal_id:
                continue
            if alarm.get("icalString"):
                out.append(str(alarm["icalString"]))
        return out

    @staticmethod
    def _recurrence_strings(profile: Mapping[str, Any], event: Mapping[str, Any]) -> list[str]:
        item_id = str(event.get("id") or "")
        cal_id = str(event.get("cal_id") or "")
        out = []
        for rule in profile.get("recurrence") or []:
            if not isinstance(rule, Mapping):
                continue
            if str(rule.get("item_id") or "") != item_id or str(rule.get("cal_id") or "") != cal_id:
                continue
            if rule.get("icalString"):
                out.append(str(rule["icalString"]))
        return out

    @staticmethod
    def _normalize(value: Any) -> str:
        return " ".join(str(value).split()).strip().casefold()

    @staticmethod
    def _parse_date(value: Any) -> date | None:
        try:
            return date.fromisoformat(str(value).strip())
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _parse_hhmm(value: Any) -> str | None:
        if value is None:
            return None
        text = str(value).strip().upper().replace(".", "")
        match = re.match(r"^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)?$", text)
        if not match:
            return None
        hour = int(match.group(1))
        minute = int(match.group(2))
        meridiem = match.group(3)
        if meridiem == "PM" and hour < 12:
            hour += 12
        if meridiem == "AM" and hour == 12:
            hour = 0
        if not (0 <= hour < 24 and 0 <= minute < 60):
            return None
        return "%02d:%02d" % (hour, minute)

    @staticmethod
    def _from_microseconds(value: Any, tz_name: Any) -> datetime | None:
        try:
            microseconds = int(value)
        except (TypeError, ValueError):
            return None
        zone = None
        if tz_name and ZoneInfo is not None:
            try:
                zone = ZoneInfo(str(tz_name))
            except Exception:
                zone = None
        if zone is not None:
            return datetime.fromtimestamp(microseconds / 1_000_000, tz=zone)
        return datetime.fromtimestamp(microseconds / 1_000_000).astimezone()

    @staticmethod
    def _reference_datetime(params: Mapping[str, Any], evidence: Mapping[str, Any]) -> datetime | None:
        declared = str(params.get("reference_time_iso") or "").strip()
        if declared:
            try:
                parsed = datetime.fromisoformat(declared)
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                return parsed
            except ValueError:
                pass
        local = str(evidence.get("reference_time_local") or "").strip()
        if local:
            try:
                parsed = datetime.fromisoformat(local)
                if parsed.tzinfo is None:
                    parsed = parsed.replace(tzinfo=timezone.utc)
                return parsed
            except ValueError:
                return None
        return None

    # ----------------------------------------------------------- final view
    @staticmethod
    def _observation_value(observation: Any, key: str, default: Any = None) -> Any:
        if observation is None:
            return default
        if isinstance(observation, Mapping):
            return observation.get(key, default)
        return getattr(observation, key, default)

    @staticmethod
    def _view_node_key(view: str) -> str:
        return "%s_window_nodes" % view.strip().casefold().replace("-", "")

    @classmethod
    def _node_text(cls, node: Mapping[str, Any]) -> str:
        return " ".join(
            str(node.get(field) or "") for field in ("text", "description", "value", "roleDescription")
        ).strip()

    @classmethod
    def _node_matches_view(cls, node: Mapping[str, Any], view: str) -> bool:
        text = cls._node_text(node)
        lowered = text.casefold()
        wanted = view.strip().casefold()
        if wanted == "month":
            return bool(MONTH_VIEW_PATTERN.search(text))
        if wanted in ("multiweek", "multi-week"):
            return "multiweek" in lowered or "multi-week" in lowered
        if wanted == "week":
            return "week" in lowered
        return bool(wanted) and wanted in lowered

    @classmethod
    def _final_view_observed(cls, observation: Any, view: str) -> dict[str, Any]:
        foreground_app = str(cls._observation_value(observation, "foreground_app", "") or "")
        nodes = cls._observation_value(observation, "ui_nodes", []) or []
        nodes = [node for node in nodes if isinstance(node, Mapping)]
        return {
            "foreground_app": foreground_app,
            "matching_nodes": [dict(node) for node in nodes if cls._node_matches_view(node, view)][:20],
            "selected_nodes": [
                dict(node) for node in nodes if node.get("AXSelected") is True or node.get("selected") is True
            ][:20],
            "calendar_selected_nodes": [
                dict(node)
                for node in nodes
                if node.get("AXSelected") is True or node.get("selected") is True
                if cls._node_matches_view(node, view)
                or any(name in cls._node_text(node).casefold() for name in CALENDAR_VIEW_NAMES)
            ][:20],
            cls._view_node_key(view): [
                dict(node)
                for node in nodes
                if str(node.get("type") or "") == "AXWindow" and cls._node_matches_view(node, view)
            ][:20],
            "ui_node_count": len(nodes),
        }
